1	package org.jsoup.safety;
2	
3	/*
4	    Thank you to Ryan Grove (wonko.com) for the Ruby HTML cleaner http://github.com/rgrove/sanitize/, which inspired
5	    this safe-list configuration, and the initial defaults.
6	 */
7	
8	import org.jsoup.helper.Validate;
9	import org.jsoup.internal.Normalizer;
10	import org.jsoup.internal.StringUtil;
11	import org.jsoup.nodes.Attribute;
12	import org.jsoup.nodes.Attributes;
13	import org.jsoup.nodes.Element;
14	
15	import java.util.Collections;
16	import java.util.HashMap;
17	import java.util.HashSet;
18	import java.util.Iterator;
19	import java.util.Map;
20	import java.util.Objects;
21	import java.util.Set;
22	
23	import static org.jsoup.internal.Normalizer.lowerCase;
24	
25	
26	/**
27	 Safelists define what HTML (elements and attributes) to allow through a {@link Cleaner}. Everything else is removed.
28	 <p>
29	 Start with one of the defaults:
30	 </p>
31	 <ul>
32	 <li>{@link #none}
33	 <li>{@link #simpleText}
34	 <li>{@link #basic}
35	 <li>{@link #basicWithImages}
36	 <li>{@link #relaxed}
37	 </ul>
38	 <p>
39	 If you need to allow more through (please be careful!), tweak a base safelist with:
40	 </p>
41	 <ul>
42	 <li>{@link #addTags(String... tagNames)}
43	 <li>{@link #addAttributes(String tagName, String... attributes)}
44	 <li>{@link #addEnforcedAttribute(String tagName, String attribute, String value)}
45	 <li>{@link #addProtocols(String tagName, String attribute, String... protocols)}
46	 </ul>
47	 <p>
48	 You can remove any setting from an existing safelist with:
49	 </p>
50	 <ul>
51	 <li>{@link #removeTags(String... tagNames)}
52	 <li>{@link #removeAttributes(String tagName, String... attributes)}
53	 <li>{@link #removeEnforcedAttribute(String tagName, String attribute)}
54	 <li>{@link #removeProtocols(String tagName, String attribute, String... removeProtocols)}
55	 </ul>
56	
57	 <p>
58	 The {@link Cleaner} and these safelists assume that you want to clean a <code>body</code> fragment of HTML (to add user
59	 supplied HTML into a templated page), and not to clean a full HTML document. If the latter is the case, you could wrap
60	 the templated document HTML around the cleaned body HTML.
61	 </p>
62	 <p>
63	 Safelists are mutable. A {@link Cleaner} uses the supplied safelist directly, so later changes affect later cleaning
64	 calls. If you want to share a safelist across threads, finish configuring it first and do not mutate it while it is in
65	 use. To build a variant from an existing configuration, use {@link #Safelist(Safelist)} to make a copy.
66	 </p>
67	 <p>
68	 If you are going to extend a safelist, please be very careful. Make sure you understand what attributes may lead to
69	 XSS attack vectors. URL attributes are particularly vulnerable and require careful validation. See 
70	 the <a href="https://owasp.org/www-community/xss-filter-evasion-cheatsheet">XSS Filter Evasion Cheat Sheet</a> for some
71	 XSS attack examples (that jsoup will safeguard against with the default Cleaner and Safelist configuration).
72	 </p>
73	 */
74	public class Safelist {
75	    private static final String All = ":all";
76	    private static final TagName AllTag = TagName.valueOf(All);
77	    private final Set<TagName> tagNames; // tags allowed, lower case. e.g. [p, br, span]
78	    private final Map<TagName, Set<AttributeKey>> attributes; // tag -> attribute[]. allowed attributes [href] for a tag.
79	    private final Map<TagName, Map<AttributeKey, AttributeValue>> enforcedAttributes; // always set these attribute values
80	    private final Map<TagName, Map<AttributeKey, Set<Protocol>>> protocols; // allowed URL protocols for attributes
81	    private boolean preserveRelativeLinks; // option to preserve relative links
82	
83	    /**
84	     This safelist allows only text nodes: any HTML Element or any Node other than a TextNode will be removed.
85	     <p>
86	     Note that the output of {@link org.jsoup.Jsoup#clean(String, Safelist)} is still <b>HTML</b> even when using
87	     this Safelist, and so any HTML entities in the output will be appropriately escaped. If you want plain text, not
88	     HTML, you should use a text method such as {@link Element#text()} instead, after cleaning the document.
89	     </p>
90	     <p>Example:</p>
91	     <pre>{@code
92	     String sourceBodyHtml = "<p>5 is &lt; 6.</p>";
93	     String html = Jsoup.clean(sourceBodyHtml, Safelist.none());
94	
95	     Cleaner cleaner = new Cleaner(Safelist.none());
96	     String text = cleaner.clean(Jsoup.parse(sourceBodyHtml)).text();
97	
98	     // html is: 5 is &lt; 6.
99	     // text is: 5 is < 6.
100	     }</pre>
101	
102	     @return safelist
103	     */
104	    public static Safelist none() {
105	        return new Safelist();
106	    }
107	
108	    /**
109	     This safelist allows only simple text formatting: <code>b, em, i, strong, u</code>. All other HTML (tags and
110	     attributes) will be removed.
111	
112	     @return safelist
113	     */
114	    public static Safelist simpleText() {
115	        return new Safelist()
116	                .addTags("b", "em", "i", "strong", "u")
117	                ;
118	    }
119	
120	    /**
121	     <p>
122	     This safelist allows a fuller range of text nodes: <code>a, b, blockquote, br, cite, code, dd, dl, dt, em, i, li,
123	     ol, p, pre, q, small, span, strike, strong, sub, sup, u, ul</code>, and appropriate attributes.
124	     </p>
125	     <p>
126	     Links (<code>a</code> elements) can point to <code>http, https, ftp, mailto</code>, and have an enforced
127	     <code>rel=nofollow</code> attribute if they link offsite (as indicated by the specified base URI).
128	     </p>
129	     <p>
130	     Does not allow images.
131	     </p>
132	
133	     @return safelist
134	     */
135	    public static Safelist basic() {
136	        return new Safelist()
137	                .addTags(
138	                        "a", "b", "blockquote", "br", "cite", "code", "dd", "dl", "dt", "em",
139	                        "i", "li", "ol", "p", "pre", "q", "small", "span", "strike", "strong", "sub",
140	                        "sup", "u", "ul")
141	
142	                .addAttributes("a", "href")
143	                .addAttributes("blockquote", "cite")
144	                .addAttributes("q", "cite")
145	
146	                .addProtocols("a", "href", "ftp", "http", "https", "mailto")
147	                .addProtocols("blockquote", "cite", "http", "https")
148	                .addProtocols("cite", "cite", "http", "https")
149	
150	                .addEnforcedAttribute("a", "rel", "nofollow") // has special handling for external links, in Cleaner
151	                ;
152	
153	    }
154	
155	    /**
156	     This safelist allows the same text tags as {@link #basic}, and also allows <code>img</code> tags, with appropriate
157	     attributes, with <code>src</code> pointing to <code>http</code> or <code>https</code>.
158	
159	     @return safelist
160	     */
161	    public static Safelist basicWithImages() {
162	        return basic()
163	                .addTags("img")
164	                .addAttributes("img", "align", "alt", "height", "src", "title", "width")
165	                .addProtocols("img", "src", "http", "https")
166	                ;
167	    }
168	
169	    /**
170	     This safelist allows a full range of text and structural body HTML: <code>a, b, blockquote, br, caption, cite,
171	     code, col, colgroup, dd, div, dl, dt, em, h1, h2, h3, h4, h5, h6, i, img, li, ol, p, pre, q, small, span, strike, strong, sub,
172	     sup, table, tbody, td, tfoot, th, thead, tr, u, ul</code>
173	     <p>
174	     Links do not have an enforced <code>rel=nofollow</code> attribute, but you can add that if desired.
175	     </p>
176	
177	     @return safelist
178	     */
179	    public static Safelist relaxed() {
180	        return new Safelist()
181	                .addTags(
182	                        "a", "b", "blockquote", "br", "caption", "cite", "code", "col",
183	                        "colgroup", "dd", "div", "dl", "dt", "em", "h1", "h2", "h3", "h4", "h5", "h6",
184	                        "i", "img", "li", "ol", "p", "pre", "q", "small", "span", "strike", "strong",
185	                        "sub", "sup", "table", "tbody", "td", "tfoot", "th", "thead", "tr", "u",
186	                        "ul")
187	
188	                .addAttributes("a", "href", "title")
189	                .addAttributes("blockquote", "cite")
190	                .addAttributes("col", "span", "width")
191	                .addAttributes("colgroup", "span", "width")
192	                .addAttributes("img", "align", "alt", "height", "src", "title", "width")
193	                .addAttributes("ol", "start", "type")
194	                .addAttributes("q", "cite")
195	                .addAttributes("table", "summary", "width")
196	                .addAttributes("td", "abbr", "axis", "colspan", "rowspan", "width")
197	                .addAttributes(
198	                        "th", "abbr", "axis", "colspan", "rowspan", "scope",
199	                        "width")
200	                .addAttributes("ul", "type")
201	
202	                .addProtocols("a", "href", "ftp", "http", "https", "mailto")
203	                .addProtocols("blockquote", "cite", "http", "https")
204	                .addProtocols("cite", "cite", "http", "https")
205	                .addProtocols("img", "src", "http", "https")
206	                .addProtocols("q", "cite", "http", "https")
207	                ;
208	    }
209	
210	    /**
211	     Create a new, empty safelist. Generally it will be better to start with a default prepared safelist instead.
212	
213	     @see #basic()
214	     @see #basicWithImages()
215	     @see #simpleText()
216	     @see #relaxed()
217	     */
218	    public Safelist() {
219	        tagNames = new HashSet<>();
220	        attributes = new HashMap<>();
221	        enforcedAttributes = new HashMap<>();
222	        protocols = new HashMap<>();
223	        preserveRelativeLinks = false;
224	    }
225	
226	    /**
227	     Deep copy an existing Safelist to a new Safelist.
228	     @param copy the Safelist to copy
229	     */
230	    public Safelist(Safelist copy) {
231	        this();
232	        tagNames.addAll(copy.tagNames);
233	        for (Map.Entry<TagName, Set<AttributeKey>> copyTagAttributes : copy.attributes.entrySet()) {
234	            attributes.put(copyTagAttributes.getKey(), new HashSet<>(copyTagAttributes.getValue()));
235	        }
236	        for (Map.Entry<TagName, Map<AttributeKey, AttributeValue>> enforcedEntry : copy.enforcedAttributes.entrySet()) {
237	            enforcedAttributes.put(enforcedEntry.getKey(), new HashMap<>(enforcedEntry.getValue()));
238	        }
239	        for (Map.Entry<TagName, Map<AttributeKey, Set<Protocol>>> protocolsEntry : copy.protocols.entrySet()) {
240	            Map<AttributeKey, Set<Protocol>> attributeProtocolsCopy = new HashMap<>();
241	            for (Map.Entry<AttributeKey, Set<Protocol>> attributeProtocols : protocolsEntry.getValue().entrySet()) {
242	                attributeProtocolsCopy.put(attributeProtocols.getKey(), new HashSet<>(attributeProtocols.getValue()));
243	            }
244	            protocols.put(protocolsEntry.getKey(), attributeProtocolsCopy);
245	        }
246	        preserveRelativeLinks = copy.preserveRelativeLinks;
247	    }
248	
249	    /**
250	     Add a list of allowed elements to a safelist. (If a tag is not allowed, it will be removed from the HTML.)
251	
252	     @param tags tag names to allow
253	     @return this (for chaining)
254	     */
255	    public Safelist addTags(String... tags) {
256	        Validate.notNull(tags);
257	
258	        for (String tagName : tags) {
259	            Validate.notEmpty(tagName);
260	            Validate.isFalse(tagName.equalsIgnoreCase("noscript"),
261	                "noscript is unsupported in Safelists, due to incompatibilities between parsers with and without script-mode enabled");
262	            tagNames.add(TagName.valueOf(tagName));
263	        }
264	        return this;
265	    }
266	
267	    /**
268	     Remove a list of allowed elements from a safelist. (If a tag is not allowed, it will be removed from the HTML.)
269	
270	     @param tags tag names to disallow
271	     @return this (for chaining)
272	     */
273	    public Safelist removeTags(String... tags) {
274	        Validate.notNull(tags);
275	
276	        for(String tag: tags) {
277	            Validate.notEmpty(tag);
278	            TagName tagName = TagName.valueOf(tag);
279	
280	            if(tagNames.remove(tagName)) { // Only look in sub-maps if tag was allowed
281	                attributes.remove(tagName);
282	                enforcedAttributes.remove(tagName);
283	                protocols.remove(tagName);
284	            }
285	        }
286	        return this;
287	    }
288	
289	    /**
290	     Add a list of allowed attributes to a tag. (If an attribute is not allowed on an element, it will be removed.)
291	     <p>
292	     E.g.: <code>addAttributes("a", "href", "class")</code> allows <code>href</code> and <code>class</code> attributes
293	     on <code>a</code> tags.
294	     </p>
295	     <p>
296	     To make an attribute valid for <b>all tags</b>, use the pseudo tag <code>:all</code>, e.g.
297	     <code>addAttributes(":all", "class")</code>.
298	     </p>
299	
300	     @param tag  The tag the attributes are for. The tag will be added to the allowed tag list if necessary.
301	     @param attributes List of valid attributes for the tag
302	     @return this (for chaining)
303	     */
304	    public Safelist addAttributes(String tag, String... attributes) {
305	        Validate.notEmpty(tag);
306	        Validate.notNull(attributes);
307	        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");
308	
309	        addTags(tag);
310	        TagName tagName = TagName.valueOf(tag);
311	        Set<AttributeKey> attributeSet = new HashSet<>();
312	        for (String key : attributes) {
313	            Validate.notEmpty(key);
314	            attributeSet.add(AttributeKey.valueOf(key));
315	        }
316	        Set<AttributeKey> currentSet = this.attributes.computeIfAbsent(tagName, k -> new HashSet<>());
317	        currentSet.addAll(attributeSet);
318	        return this;
319	    }
320	
321	    /**
322	     Remove a list of allowed attributes from a tag. (If an attribute is not allowed on an element, it will be removed.)
323	     <p>
324	     E.g.: <code>removeAttributes("a", "href", "class")</code> disallows <code>href</code> and <code>class</code>
325	     attributes on <code>a</code> tags.
326	     </p>
327	     <p>
328	     To make an attribute invalid for <b>all tags</b>, use the pseudo tag <code>:all</code>, e.g.
329	     <code>removeAttributes(":all", "class")</code>.
330	     </p>
331	
332	     @param tag  The tag the attributes are for.
333	     @param attributes List of invalid attributes for the tag
334	     @return this (for chaining)
335	     */
336	    public Safelist removeAttributes(String tag, String... attributes) {
337	        Validate.notEmpty(tag);
338	        Validate.notNull(attributes);
339	        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");
340	
341	        TagName tagName = TagName.valueOf(tag);
342	        Set<AttributeKey> attributeSet = new HashSet<>();
343	        for (String key : attributes) {
344	            Validate.notEmpty(key);
345	            attributeSet.add(AttributeKey.valueOf(key));
346	        }
347	        if(tagNames.contains(tagName) && this.attributes.containsKey(tagName)) { // Only look in sub-maps if tag was allowed
348	            Set<AttributeKey> currentSet = this.attributes.get(tagName);
349	            currentSet.removeAll(attributeSet);
350	
351	            if(currentSet.isEmpty()) // Remove tag from attribute map if no attributes are allowed for tag
352	                this.attributes.remove(tagName);
353	        }
354	        if(tag.equals(All)) { // Attribute needs to be removed from all individually set tags
355	            Iterator<Map.Entry<TagName, Set<AttributeKey>>> it = this.attributes.entrySet().iterator();
356	            while (it.hasNext()) {
357	                Map.Entry<TagName, Set<AttributeKey>> entry = it.next();
358	                Set<AttributeKey> currentSet = entry.getValue();
359	                currentSet.removeAll(attributeSet);
360	                if(currentSet.isEmpty()) // Remove tag from attribute map if no attributes are allowed for tag
361	                    it.remove();
362	            }
363	        }
364	        return this;
365	    }
366	
367	    /**
368	     Add an enforced attribute to a tag. An enforced attribute will always be added to the element. If the element
369	     already has the attribute set, it will be overridden with this value.
370	     <p>
371	     E.g.: <code>addEnforcedAttribute("a", "rel", "nofollow")</code> will make all <code>a</code> tags output as
372	     <code>&lt;a href="..." rel="nofollow"&gt;</code>
373	     </p>
374	
375	     @param tag   The tag the enforced attribute is for. The tag will be added to the allowed tag list if necessary.
376	     @param attribute   The attribute name
377	     @param value The enforced attribute value
378	     @return this (for chaining)
379	     */
380	    public Safelist addEnforcedAttribute(String tag, String attribute, String value) {
381	        Validate.notEmpty(tag);
382	        Validate.notEmpty(attribute);
383	        Validate.notEmpty(value);
384	
385	        TagName tagName = TagName.valueOf(tag);
386	        tagNames.add(tagName);
387	        AttributeKey attrKey = AttributeKey.valueOf(attribute);
388	        AttributeValue attrVal = AttributeValue.valueOf(value);
389	
390	        Map<AttributeKey, AttributeValue> attrMap = enforcedAttributes.computeIfAbsent(tagName, k -> new HashMap<>());
391	        attrMap.put(attrKey, attrVal);
392	        return this;
393	    }
394	
395	    /**
396	     Remove a previously configured enforced attribute from a tag.
397	
398	     @param tag   The tag the enforced attribute is for.
399	     @param attribute   The attribute name
400	     @return this (for chaining)
401	     */
402	    public Safelist removeEnforcedAttribute(String tag, String attribute) {
403	        Validate.notEmpty(tag);
404	        Validate.notEmpty(attribute);
405	
406	        TagName tagName = TagName.valueOf(tag);
407	        if(tagNames.contains(tagName) && enforcedAttributes.containsKey(tagName)) {
408	            AttributeKey attrKey = AttributeKey.valueOf(attribute);
409	            Map<AttributeKey, AttributeValue> attrMap = enforcedAttributes.get(tagName);
410	            attrMap.remove(attrKey);
411	
412	            if(attrMap.isEmpty()) // Remove tag from enforced attribute map if no enforced attributes are present
413	                enforcedAttributes.remove(tagName);
414	        }
415	        return this;
416	    }
417	
418	    /**
419	     * Configure this Safelist to preserve relative links in an element's URL attribute, or convert them to absolute
420	     * links. By default, this is <b>false</b>: URLs will be  made absolute (e.g. start with an allowed protocol, like
421	     * e.g. {@code http://}.
422	     *
423	     * @param preserve {@code true} to allow relative links, {@code false} (default) to deny
424	     * @return this Safelist, for chaining.
425	     * @see #addProtocols
426	     */
427	    public Safelist preserveRelativeLinks(boolean preserve) {
428	        preserveRelativeLinks = preserve;
429	        return this;
430	    }
431	
432	    /**
433	     * Get the current setting for preserving relative links.
434	     * @return {@code true} if relative links are preserved, {@code false} if they are converted to absolute.
435	     */
436	    public boolean preserveRelativeLinks() {
437	        return preserveRelativeLinks;
438	    }
439	
440	    /**
441	     Add allowed URL protocols for an element's URL attribute. This restricts the possible values of the attribute to
442	     URLs with the defined protocol.
443	     <p>
444	     E.g.: <code>addProtocols("a", "href", "ftp", "http", "https")</code>
445	     </p>
446	     <p>
447	     To allow a link to an in-page URL anchor (i.e. <code>&lt;a href="#anchor"&gt;</code>, add a <code>#</code>:<br>
448	     E.g.: <code>addProtocols("a", "href", "#")</code>
449	     </p>
450	
451	     @param tag       Tag the URL protocol is for
452	     @param attribute       Attribute name
453	     @param protocols List of valid protocols
454	     @return this, for chaining
455	     */
456	    public Safelist addProtocols(String tag, String attribute, String... protocols) {
457	        Validate.notEmpty(tag);
458	        Validate.notEmpty(attribute);
459	        Validate.notNull(protocols);
460	
461	        TagName tagName = TagName.valueOf(tag);
462	        AttributeKey attrKey = AttributeKey.valueOf(attribute);
463	        Map<AttributeKey, Set<Protocol>> attrMap = this.protocols.computeIfAbsent(tagName, k -> new HashMap<>());
464	        Set<Protocol> protSet = attrMap.computeIfAbsent(attrKey, k -> new HashSet<>());
465	
466	        for (String protocol : protocols) {
467	            Validate.notEmpty(protocol);
468	            Protocol prot = Protocol.valueOf(protocol);
469	            protSet.add(prot);
470	        }
471	        return this;
472	    }
473	
474	    /**
475	     Remove allowed URL protocols for an element's URL attribute. If you remove all protocols for an attribute, that
476	     attribute will allow any protocol.
477	     <p>
478	     E.g.: <code>removeProtocols("a", "href", "ftp")</code>
479	     </p>
480	
481	     @param tag Tag the URL protocol is for
482	     @param attribute Attribute name
483	     @param removeProtocols List of invalid protocols
484	     @return this, for chaining
485	     */
486	    public Safelist removeProtocols(String tag, String attribute, String... removeProtocols) {
487	        Validate.notEmpty(tag);
488	        Validate.notEmpty(attribute);
489	        Validate.notNull(removeProtocols);
490	
491	        TagName tagName = TagName.valueOf(tag);
492	        AttributeKey attr = AttributeKey.valueOf(attribute);
493	
494	        // make sure that what we're removing actually exists; otherwise can open the tag to any data and that can
495	        // be surprising
496	        Validate.isTrue(protocols.containsKey(tagName), "Cannot remove a protocol that is not set.");
497	        Map<AttributeKey, Set<Protocol>> tagProtocols = protocols.get(tagName);
498	        Validate.isTrue(tagProtocols.containsKey(attr), "Cannot remove a protocol that is not set.");
499	
500	        Set<Protocol> attrProtocols = tagProtocols.get(attr);
501	        for (String protocol : removeProtocols) {
502	            Validate.notEmpty(protocol);
503	            attrProtocols.remove(Protocol.valueOf(protocol));
504	        }
505	
506	        if (attrProtocols.isEmpty()) { // Remove protocol set if empty
507	            tagProtocols.remove(attr);
508	            if (tagProtocols.isEmpty()) // Remove entry for tag if empty
509	                protocols.remove(tagName);
510	        }
511	        return this;
512	    }
513	
514	    /**
515	     * Test if the supplied tag is allowed by this safelist.
516	     * @param tag test tag
517	     * @return true if allowed
518	     */
519	    public boolean isSafeTag(String tag) {
520	        return tagNames.contains(TagName.valueOf(tag));
521	    }
522	
523	    /**
524	     * Test if the supplied attribute is allowed by this safelist for this tag.
525	     * <p>This method does not modify the input element or attribute.</p>
526	     * @param tagName tag to consider allowing the attribute in
527	     * @param el element under test, to confirm protocol
528	     * @param attr attribute under test
529	     * @return true if allowed
530	     */
531	    public boolean isSafeAttribute(String tagName, Element el, Attribute attr) {
532	        TagName tag = TagName.valueOf(tagName);
533	        AttributeKey key = AttributeKey.valueOf(attr.getKey());
534	
535	        Set<AttributeKey> okSet = attributes.get(tag);
536	        if (okSet != null && okSet.contains(key)) {
537	            if (protocols.containsKey(tag)) {
538	                Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
539	                // ok if not defined protocol; otherwise test
540	                return !attrProts.containsKey(key) || isSafeProtocol(getProtocolValue(el, attr), attrProts.get(key));
541	            } else { // attribute found, no protocols defined, so OK
542	                return true;
543	            }
544	        }
545	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
546	        if (enforcedSet != null && enforcedSet.containsKey(key)) {
547	            // enforced attr key was LCed via AttributeKey.valueOf(attr.getKey()),
548	            // if the input already has that exact value, treat it as safe
549	            return enforcedSet.get(key).equals(AttributeValue.valueOf(attr.getValue()));
550	        }
551	        // no attributes defined for tag, try :all tag
552	        return !tagName.equals(All) && isSafeAttribute(All, el, attr);
553	    }
554	
555	    private String getProtocolValue(Element el, Attribute attr) {
556	        String value = el.absUrl(attr.getKey());
557	        if (value.isEmpty() && !StringUtil.hasHttpScheme(attr.getValue()))
558	            value = attr.getValue(); // if it could not be made abs, run as-is to allow custom unknown protocols
559	        return value;
560	    }
561	
562	    /**
563	     Test if the supplied attribute is structurally allowed on this tag by the safelist, without applying the
564	     whole-value protocol check. This is used for attributes whose value is validated piece by piece by the
565	     {@link Cleaner} (currently {@code srcset}, whose individual candidate URLs are checked separately); ordinary
566	     attributes use {@link #isSafeAttribute(String, Element, Attribute)}.
567	     @param tagName tag to consider allowing the attribute in
568	     @param el element under test
569	     @param attr attribute under test
570	     @return true if the attribute is allowed by the tag/attribute configuration, regardless of its value
571	     */
572	    boolean isAllowedAttribute(String tagName, Element el, Attribute attr) {
573	        TagName tag = TagName.valueOf(tagName);
574	        AttributeKey key = AttributeKey.valueOf(attr.getKey());
575	
576	        Set<AttributeKey> okSet = attributes.get(tag);
577	        if (okSet != null && okSet.contains(key)) return true;
578	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
579	        if (enforcedSet != null && enforcedSet.containsKey(key)) {
580	            return enforcedSet.get(key).equals(AttributeValue.valueOf(attr.getValue()));
581	        }
582	        return !tagName.equals(All) && isAllowedAttribute(All, el, attr);
583	    }
584	
585	    /**
586	     Get the allowed protocol set that governs the individual URLs inside a {@code srcset} attribute on the given
587	     tag. Because a {@code srcset} value carries multiple candidate URLs, each one is checked against a protocol
588	     policy in a fixed, stable order:
589	     <ol>
590	     <li>the tag's own explicit {@code srcset} policy;</li>
591	     <li>the tag's own {@code src} policy;</li>
592	     <li>the global {@code :all} {@code srcset}, then {@code src}, policy &mdash; but only when the tag declares no
593	     policy of its own;</li>
594	     <li>for a {@code source} element only, the fallback {@code img} tag's {@code srcset}/{@code src} policy, and only
595	     when the {@code img} tag is itself whitelisted (a {@code source} inside a {@code picture} is an alternative to
596	     that whitelisted fallback {@code img}).</li>
597	     </ol>
598	     A policy configured for one element can never widen or narrow another element: {@code source} never borrows an
599	     {@code img} policy that the safelist does not also whitelist {@code img} to carry, and {@code img} is never
600	     affected by {@code source} policy.
601	     @param tagName the tag carrying the srcset attribute
602	     @return the allowed protocols (never null; an empty set means no protocol restriction applies)
603	     */
604	    Set<Protocol> srcsetProtocols(String tagName) {
605	        TagName tag = TagName.valueOf(tagName);
606	        AttributeKey srcset = AttributeKey.valueOf("srcset");
607	        AttributeKey src = AttributeKey.valueOf("src");
608	
609	        Set<Protocol> allowed = protocolsFor(tag, srcset);
610	        if (allowed == null) allowed = protocolsFor(tag, src);
611	        if (allowed == null && !tag.equals(AllTag)) {
612	            // global rules apply only when the tag declares no policy of its own
613	            allowed = protocolsFor(AllTag, srcset);
614	            if (allowed == null) allowed = protocolsFor(AllTag, src);
615	        }
616	        if (allowed == null && tag.equals(SourceTag) && tagNames.contains(ImgTag)) {
617	            // no own or global policy, and the fallback <img> tag is actually whitelisted: judge the <source>
618	            // candidates by the same image policy so a source and the fallback img in one picture match
619	            allowed = protocolsFor(ImgTag, srcset);
620	            if (allowed == null) allowed = protocolsFor(ImgTag, src);
621	        }
622	        return allowed == null ? Collections.emptySet() : allowed;
623	    }
624	
625	    private static final TagName ImgTag = TagName.valueOf("img");
626	    private static final TagName SourceTag = TagName.valueOf("source");
627	
628	    private Set<Protocol> protocolsFor(TagName tag, AttributeKey key) {
629	        Map<AttributeKey, Set<Protocol>> byAttribute = protocols.get(tag);
630	        return byAttribute == null ? null : byAttribute.get(key);
631	    }
632	
633	    private boolean isSafeProtocol(String value, Set<Protocol> protocols) {
634	        for (Protocol protocol : protocols) {
635	            String prot = protocol.toString();
636	
637	            if (prot.equals("#")) { // allows anchor links
638	                if (isValidAnchor(value)) {
639	                    return true;
640	                } else {
641	                    continue;
642	                }
643	            }
644	
645	            String lc = lowerCase(value);
646	            if (lc.startsWith(prot)
647	                && lc.length() > prot.length()
648	                && lc.charAt(prot.length()) == ':') {
649	                return true;
650	            }
651	        }
652	        return false;
653	    }
654	
655	    /**
656	     Check if a URL attribute should be normalized to an absolute URL in the cleaned output. Uses the configured
657	     protocols for that tag+attribute pair, falling back to {@code :all} only if the tag does not define the
658	     attribute.
659	     */
660	    boolean shouldAbsUrl(String tagName, String attrKey) {
661	        if (preserveRelativeLinks) return false;
662	        return shouldAbsUrl(TagName.valueOf(tagName), AttributeKey.valueOf(attrKey));
663	    }
664	
665	    private boolean shouldAbsUrl(TagName tag, AttributeKey key) {
666	        Set<AttributeKey> allowedAttrs = attributes.get(tag);
667	        if (allowedAttrs != null && allowedAttrs.contains(key)) {
668	            Map<AttributeKey, Set<Protocol>> protocolsByAttr = protocols.get(tag);
669	            return protocolsByAttr != null && protocolsByAttr.containsKey(key);
670	        }
671	
672	        Map<AttributeKey, AttributeValue> enforcedAttrs = enforcedAttributes.get(tag);
673	        if (enforcedAttrs != null && enforcedAttrs.containsKey(key)) return false;
674	
675	        return !tag.equals(AllTag) && shouldAbsUrl(AllTag, key);
676	    }
677	
678	    private static boolean isValidAnchor(String value) {
679	        return value.startsWith("#") && !value.matches(".*\\s.*");
680	    }
681	
682	    /**
683	     Gets the Attributes that should be enforced for a given tag
684	     * @param tagName the tag
685	     * @return the attributes that will be enforced; empty if none are set for the given tag
686	     */
687	    public Attributes getEnforcedAttributes(String tagName) {
688	        Attributes attrs = new Attributes();
689	        TagName tag = TagName.valueOf(tagName);
690	        if (enforcedAttributes.containsKey(tag)) {
691	            Map<AttributeKey, AttributeValue> keyVals = enforcedAttributes.get(tag);
692	            for (Map.Entry<AttributeKey, AttributeValue> entry : keyVals.entrySet()) {
693	                attrs.put(entry.getKey().toString(), entry.getValue().toString());
694	            }
695	        }
696	        return attrs;
697	    }
698	    
699	    // named types for config. All just hold strings, but here for my sanity.
700	
701	    static class TagName extends TypedValue {
702	        TagName(String value) {
703	            super(value);
704	        }
705	
706	        static TagName valueOf(String value) {
707	            return new TagName(Normalizer.lowerCase(value));
708	        }
709	    }
710	
711	    static class AttributeKey extends TypedValue {
712	        AttributeKey(String value) {
713	            super(value);
714	        }
715	
716	        static AttributeKey valueOf(String value) {
717	            return new AttributeKey(Normalizer.lowerCase(value));
718	        }
719	    }
720	
721	    static class AttributeValue extends TypedValue {
722	        AttributeValue(String value) {
723	            super(value);
724	        }
725	
726	        static AttributeValue valueOf(String value) {
727	            return new AttributeValue(value);
728	        }
729	    }
730	
731	    static class Protocol extends TypedValue {
732	        Protocol(String value) {
733	            super(value);
734	        }
735	
736	        static Protocol valueOf(String value) {
737	            return new Protocol(value);
738	        }
739	    }
740	
741	    abstract static class TypedValue {
742	        private final String value;
743	
744	        TypedValue(String value) {
745	            Validate.notNull(value);
746	            this.value = value;
747	        }
748	
749	        @Override
750	        public int hashCode() {
751	            return value.hashCode();
752	        }
753	
754	        @Override
755	        public boolean equals(Object obj) {
756	            if (this == obj) return true;
757	            if (obj == null || getClass() != obj.getClass()) return false;
758	            TypedValue other = (TypedValue) obj;
759	            return Objects.equals(value, other.value);
760	        }
761	
762	        @Override
763	        public String toString() {
764	            return value;
765	        }
766	    }
767	}
