            if (c == '+' || c == '-' || c == '*' || c == '/') { i++; continue; }
            if (c == '(' || c == ')') { i++; continue; }
            int numEnd = readNumber(body, i);
            if (numEnd == i) return false; // a letter here that is not part of a unit is invalid
            int unitEnd = readUnit(body, numEnd);
