    }

    private static boolean isUnit(String s) {
        return readUnit(s, 0) == s.length() && !s.isEmpty();
    }

    private static boolean isBalanced(String s) {
        int depth = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
