     */
    private static int readNumber(String s, int start) {
        int i = start;
        int len = s.length();
        int intDigits = 0;
        while (i < len && isAsciiDigit(s.charAt(i))) { intDigits++; i++; }
        if (i < len && s.charAt(i) == '.') {
            int j = i + 1;
