/**
 Validate an optional media condition: non-empty, parenthesis-balanced (groups may nest), and limited to letters,
 digits, whitespace, hyphens, colons, dots, comparison operators, and parentheses. A bare pair of empty
 parentheses, an empty group, or any other character invalidates the condition.
 */
private static boolean isValidMedia(String media) {
    if (media.isEmpty()) return false;
    int depth = 0;
    int[] groupContent = new int[Math.max(8, count('(', media) + 1)];
    for (int i = 0; i < media.length(); i++) {
        char c = media.charAt(i);
        if (c == '(') {
            depth++;
            if (depth < groupContent.length) groupContent[depth] = 0;
            continue;
        }
        if (c == ')') {
            if (depth == 0 || groupContent[depth] == 0) return false; // unmatched or empty group
            depth--;
            groupContent[depth] = 1;
            continue;
        }
        if (!isMediaChar(c)) return false;
        if (!StringUtil.isWhitespace(c)) groupContent[depth] = 1;
    }
    return depth == 0;
}

