import org.jsoup.Jsoup;
import org.jsoup.safety.*;
public class SizesDemo {
  public static void main(String[] a) {
    Safelist sl = Safelist.relaxed().addTags("picture","source")
      .addAttributes("img","srcset","sizes")
      .addAttributes("source","srcset","sizes","media","type");
    String html = "<picture><source media=\"(min-width: 800px)\" sizes=\"(min-width: 800px) 50vw, bogus, calc(100vw - 16px)\" srcset=\"javascript:x 1x, http://e/a.jpg 2x\">"
      + "<img sizes=\"100px; evil: x, 200px, (unclosed, 300px\" srcset=\"http://e/f.jpg\" alt=\"hi\"></picture>";
    System.out.println(Jsoup.clean(html, "http://example.com/", sl));
    String again = Jsoup.clean(Jsoup.clean(html, "http://example.com/", sl), "http://example.com/", sl);
    System.out.println("idempotent=" + again.equals(Jsoup.clean(html, "http://example.com/", sl)));
  }
}
